insert into anagrafica.catalogo_patologie
  (codice, nome, sinonimi, tipo, area, esenzione, orpha, icd9cm, descrizione, segni_allarme,
   diagnosi, follow_up, specialisti, emergenza, note, fonti, ordine) values
('sindrome_nefrosica', 'Sindrome nefrosica idiopatica del bambino', array['Nefrosi lipoidea', 'Sindrome nefrosica a lesioni minime', 'Sindrome nefrosica steroido-sensibile'], 'cronica', 'nefro', null, null, array['581.3', '581.9'], 'Proteinuria di grado nefrosico con ipoalbuminemia ed edemi; nel bambino è quasi sempre idiopatica, per lo più a lesioni minime e sensibile ai corticosteroidi, con frequenti recidive.', array['Edema delle palpebre al risveglio, poi di caviglie, scroto o addome', 'Urine schiumose', 'Aumento di peso rapido', 'Proteinuria marcata allo stick urinario'], 'Esame urine con rapporto proteine/creatinina, albumina e lipidi nel sangue, funzione renale, complemento; biopsia renale solo nei casi atipici o resistenti agli steroidi.', array['Nefrologo pediatra: terapia steroidea secondo le raccomandazioni IPNA', 'Stick urinario a domicilio con diario (remissione e recidive)', 'Pressione arteriosa, crescita, effetti degli steroidi (vista, osso, peso)', 'Vaccinazioni: pneumococco, influenza e varicella raccomandate; vaccini vivi rinviati durante steroidi ad alte dosi o immunosoppressori'], 'Nefrologo pediatra', 'Dolore addominale con febbre (peritonite), poca urina, mani fredde e malessere (ipovolemia), gonfiore o dolore di un arto o cefalea intensa (trombosi): pronto soccorso.', 'Non ha un codice di malattia rara (la glomerulopatia a lesioni minime è esclusa da RJG020). L''esenzione 061 «patologie renali croniche» riguarda solo alcune forme istologiche con riduzione stabile della funzione renale: verificare con la ASL.', '[{"titolo": "Trautmann A. et al. IPNA clinical practice recommendations for the diagnosis and management of children with steroid-sensitive nephrotic syndrome, Pediatr Nephrol 2023", "url": "https://doi.org/10.1007/s00467-022-05739-3"}]'::jsonb, 890),
('sindrome_nefrosica_genetica', 'Sindrome nefrosica congenita e steroido-resistente', array['Sindrome nefrosica di tipo finlandese', 'SRNS'], 'rara', 'nefro', 'RJG020', 564127, '{}'::text[], 'Forme che esordiscono nei primi mesi di vita (congenita, spesso genetica: NPHS1, NPHS2, WT1) o che non rispondono a 4 settimane di corticosteroidi (steroido-resistente).', array['Edemi e proteinuria massiva nei primi 3 mesi di vita', 'Placenta voluminosa', 'Mancata remissione dopo 4 settimane di steroidi', 'Familiari con malattia renale'], 'Biopsia renale e analisi genetica in centro nefrologico; studio delle cause secondarie.', array['Nefrologo pediatra del centro: immunosoppressori o terapia di supporto secondo la causa', 'Funzione renale, pressione, crescita e nutrizione'], 'Nefrologo pediatra', 'Infezioni, trombosi e ipovolemia come nella sindrome nefrosica idiopatica: valutazione urgente.', 'Compresa nel gruppo RJG020 (glomerulopatie primitive) come voce dell''elenco della Rete lombarda; verificare il codice con il presidio della rete malattie rare.', '[{"titolo": "Trautmann A. et al. IPNA clinical practice recommendations for the diagnosis and management of children with steroid-resistant nephrotic syndrome, Pediatr Nephrol 2020", "url": "https://doi.org/10.1007/s00467-020-04519-1"}]'::jsonb, 900),
('henoch_schonlein', 'Porpora di Henoch-Schönlein ricorrente (vasculite a IgA)', array['Vasculite a IgA', 'Porpora anafilattoide'], 'rara', 'nefro', 'RD0030', 761, '{}'::text[], 'Vasculite dei piccoli vasi, la più frequente in età pediatrica; l''esenzione riguarda le forme ricorrenti.', array['Porpora palpabile su gambe e glutei', 'Dolori e gonfiori articolari', 'Dolore addominale, sangue nelle feci', 'Ematuria o proteinuria, ipertensione'], 'Diagnosi clinica (criteri EULAR/PRINTO/PRES); esame urine, funzione renale e pressione.', array['Esame urine e pressione per almeno 6–12 mesi dall''esordio', 'Nefrologo pediatra se proteinuria persistente, sindrome nefrosica o funzione renale ridotta'], 'Pediatra, nefrologo pediatra', 'Dolore addominale intenso o vomito (rischio di invaginazione intestinale), oppure poca urina, edemi o ipertensione: valutazione urgente.', null, '[]'::jsonb, 910),
('alport', 'Sindrome di Alport', '{}'::text[], 'rara', 'nefro', 'RN1360', 63, '{}'::text[], 'Malattia del collagene di tipo IV (geni COL4A3, COL4A4, COL4A5) con nefropatia progressiva, sordità e anomalie oculari.', array['Ematuria microscopica persistente fin dall''infanzia', 'Proteinuria che compare nel tempo', 'Ipoacusia neurosensoriale', 'Familiari con nefropatia, dialisi o sordità'], 'Analisi genetica dei geni del collagene IV; biopsia renale nei casi dubbi.', array['Nefrologo pediatra: farmaci antiproteinurici precoci', 'Audiometria e visita oculistica periodiche', 'Consulenza genetica alla famiglia'], 'Nefrologo pediatra', null, null, '[]'::jsonb, 920),
('denys_drash', 'Sindrome di Denys-Drash', '{}'::text[], 'rara', 'nefro', 'RN1430', 220, '{}'::text[], 'Malattia da varianti del gene WT1 con nefropatia precoce, anomalie dello sviluppo genitale e rischio di tumore di Wilms.', array['Sindrome nefrosica nei primi anni di vita', 'Genitali ambigui in soggetto 46,XY', 'Massa addominale (Wilms)'], 'Analisi del gene WT1, cariotipo.', array['Nefrologo pediatra', 'Sorveglianza ecografica del tumore di Wilms', 'Endocrinologo e chirurgo pediatra'], 'Nefrologo pediatra, oncologo pediatra', null, null, '[]'::jsonb, 930),
('tubulopatie', 'Tubulopatie primitive (Bartter, Gitelman, Dent, acidosi tubulare)', array['Sindrome di Bartter', 'Sindrome di Gitelman', 'Malattia di Dent', 'Acidosi tubulare renale'], 'rara', 'nefro', 'RJG010', null, '{}'::text[], 'Difetti ereditari del trasporto tubulare renale di sali, acqua, acidi o proteine a basso peso molecolare.', array['Poliuria e polidipsia, disidratazione', 'Scarsa crescita, vomito', 'Crampi, debolezza (ipokaliemia)', 'Calcoli o nefrocalcinosi, rachitismo'], 'Elettroliti, emogasanalisi, esami urinari specifici, ecografia renale, analisi genetica.', array['Nefrologo pediatra: integrazioni di sali e farmaci specifici', 'Crescita ed elettroliti periodici'], 'Nefrologo pediatra', 'Vomito o diarrea: rischio di disidratazione e squilibri elettrolitici, valutazione rapida.', null, '[]'::jsonb, 940),
('cistinosi', 'Cistinosi', '{}'::text[], 'rara', 'nefro', 'RCG040', 213, '{}'::text[], 'Malattia lisosomiale con accumulo di cistina; la forma infantile causa sindrome di Fanconi renale nel primo anno.', array['Dal primo anno: poliuria, polidipsia, disidratazione', 'Scarsa crescita, rachitismo', 'Fotofobia (cristalli corneali)'], 'Dosaggio della cistina nei leucociti, visita oculistica con lampada a fessura, analisi genetica.', array['Centro di nefrologia pediatrica e malattie metaboliche: cisteamina', 'Funzione renale, tiroide, crescita, occhi'], 'Nefrologo pediatra', null, 'Esente con il codice RCG040 (difetti del metabolismo e del trasporto degli aminoacidi).', '[]'::jsonb, 950),
('arpkd', 'Rene policistico autosomico recessivo', '{}'::text[], 'rara', 'nefro', 'RJ0040', 731, '{}'::text[], 'Malattia cistica renale ed epatica (gene PKHD1) che si manifesta spesso già in epoca prenatale.', array['Reni ingranditi e iperecogeni all''ecografia prenatale, oligoidramnios', 'Ipertensione arteriosa nel lattante', 'Epatomegalia, fibrosi epatica, splenomegalia'], 'Ecografia renale ed epatica, analisi genetica.', array['Nefrologo ed epatologo pediatra', 'Pressione, funzione renale, ipertensione portale'], 'Nefrologo pediatra', null, null, '[]'::jsonb, 960),
('malattia_renale_cistica', 'Malattie renali cistiche genetiche (esclusa la forma autosomica dominante)', '{}'::text[], 'rara', 'nefro', 'RNG261', null, '{}'::text[], 'Gruppo di nefropatie cistiche ereditarie (es. nefronoftisi, malattia cistica glomerulare).', array['Poliuria e polidipsia, enuresi secondaria', 'Anemia, scarsa crescita', 'Cisti renali all''ecografia'], 'Ecografia renale, funzione renale, analisi genetica.', array['Nefrologo pediatra', 'Valutazioni extrarenali (occhio, fegato) secondo la forma'], 'Nefrologo pediatra', null, 'Il rene policistico autosomico dominante ha invece il codice di patologia cronica 062.', '[]'::jsonb, 970),
('diabete_insipido_nefrogenico', 'Diabete insipido nefrogenico', '{}'::text[], 'rara', 'nefro', 'RJ0010', 223, '{}'::text[], 'Incapacità del rene di concentrare le urine per resistenza all''ormone antidiuretico, di solito legata all''X (gene AVPR2).', array['Lattante con poliuria, febbre senza causa, irritabilità, scarsa crescita', 'Sete intensa, disidratazione ipernatriemica'], 'Osmolalità di plasma e urine, test con desmopressina, analisi genetica.', array['Nefrologo pediatra: apporto di acqua, dieta e farmaci', 'Ecografia delle vie urinarie (dilatazioni)'], 'Nefrologo pediatra', 'Vomito, diarrea o impossibilità a bere: rischio di disidratazione ipernatriemica grave, pronto soccorso.', null, '[]'::jsonb, 980)
on conflict (codice) do nothing;

